require dirname(__DIR__).'/bootstrap.php';require __DIR__.'/admin-layout.php';admin_required();$q=$pdo->prepare('SELECT * FROM orders WHERE id=?');$q->execute([(int)($_GET['id']??0)]);$o=$q->fetch();admin_header('Order details');if(!$o){echo '<p>Order not found.</p>';admin_footer();exit;}$q=$pdo->prepare('SELECT * FROM order_items WHERE order_id=?');$q->execute([$o['id']);$items=$q->fetchAll(); ?><div class="admin-panel"><h2><?=e($o['order_number'])?></h2><p><?=e($o['customer_name'])?> · <?=e($o['email'])?> · <?=e($o['whatsapp'])?></p><p><?=e($o['address'])?>, <?=e($o['district'])?>, <?=e($o['city'])?>, <?=e($o['province'])?> <?=e($o['postal_code'])?></p><p>Notes: <?=e($o['notes'])?></p><div class="table-wrap"><table><tr><th>Product</th><th>SKU</th><th>Qty</th><th>Price</th><th>Total</th></tr><?php foreach($items as $i):?><tr><td><?=e($i['product_name'])?></td><td><?=e($i['sku'])?></td><td><?=$i['quantity']?></td><td><?=money((float)$i['unit_price'])?></td><td><?=money((float)$i['line_total'])?></td></tr><?php endforeach;?></table></div><p>Subtotal <?=money((float)$o['subtotal'])?> · Shipping <?=money((float)$o['shipping_fee'])?> · <b>Total <?=money((float)$o['total'])?></b></p><p>Status: <?=e($o['status'])?> · Payment: <?=e($o['payment_status'])?></p></div><?php admin_footer(); ?>
